os.makedirs(WORK, exist_ok=True)
open(WORK+"/go.mod","w").write("module example.com/sp\n\ngo 1.21\n")
MARK="zzz.marker/general"

def probe(paths, batch=2000):
    res=[]
    paths=list(paths)
    for i in range(0,len(paths),batch):
        chunk=paths[i:i+batch]+[MARK]
        src="package main\n\nimport (\n"+"".join('\t"%s"\n'%p for p in chunk)+")\n"
        open(WORK+"/p.go","w").write(src)
        out=subprocess.run(["/workspace/executable","-output","stdout","p.go"],
                           capture_output=True,text=True,cwd=WORK)
        if out.returncode!=0:
            print("ERR",out.returncode,out.stderr[-800:],file=sys.stderr); sys.exit(1)
        lines=out.stdout.splitlines()
        s=lines.index("import ("); e=lines.index(")",s)
        groups=[[]]
        for ln in lines[s+1:e]:
            if not ln.strip(): groups.append([]); continue
            groups[-1].append(ln.strip().strip('"'))
        gi=next(i for i,g in enumerate(groups) if MARK in g)
        for j,g in enumerate(groups):
            if j!=gi: res.extend(g)
    return res

def words(maxlen, prefix=""):
    a=string.ascii_lowercase
    for n in range(1,maxlen+1):
        for t in itertools.product(a,repeat=n):
            yield prefix+"".join(t)

if __name__=="__main__":
    mode=sys.argv[1]
    if mode=="file":
        for p in probe([l.strip() for l in open(sys.argv[2]) if l.strip()]): print(p)
    elif mode=="sweep":
        maxlen=int(sys.argv[2]); prefix=sys.argv[3] if len(sys.argv)>3 else ""
        for p in probe(words(maxlen,prefix)): print(p)
