package reviser

import (
	"fmt"
	"go/ast"
	"go/token"
	"sort"
	"strconv"
	"strings"
)

// importDef is a single import statement reduced to the parts that survive a
// rewrite: the (optional) alias, the quoted path and the comment that sits on
// the same line as the import.
type importDef struct {
	alias   string
	path    string
	comment string
}

// named reports whether the import carries an explicit alias. Blank and dot
// imports count as named.
func (i importDef) named() bool {
	return i.alias != ""
}

func (i importDef) String() string {
	var sb strings.Builder
	if i.alias != "" {
		sb.WriteString(i.alias)
		sb.WriteByte(' ')
	}
	sb.WriteString(strconv.Quote(i.path))
	if i.comment != "" {
		sb.WriteByte(' ')
		sb.WriteString(i.comment)
	}
	return sb.String()
}

// collectImports flattens every import declaration of the file into a single
// ordered slice. Only same-line comments are carried over; doc comments and
// free floating comments inside the parentheses are dropped, mirroring the
// reference implementation.
func collectImports(decls []*ast.GenDecl) []importDef {
	var out []importDef
	for _, decl := range decls {
		for _, spec := range decl.Specs {
			imp, ok := spec.(*ast.ImportSpec)
			if !ok {
				continue
			}
			path, err := strconv.Unquote(imp.Path.Value)
			if err != nil {
				path = strings.Trim(imp.Path.Value, `"`)
			}
			def := importDef{path: path}
			if imp.Name != nil {
				def.alias = imp.Name.Name
			}
			def.comment = commentText(imp.Comment)
			out = append(out, def)
		}
	}
	return out
}

func commentText(group *ast.CommentGroup) string {
	if group == nil || len(group.List) == 0 {
		return ""
	}
	parts := make([]string, 0, len(group.List))
	for _, c := range group.List {
		parts = append(parts, c.Text)
	}
	return strings.Join(parts, " ")
}

// importDecls returns every top level import declaration in source order.
func importDecls(f *ast.File) []*ast.GenDecl {
	var out []*ast.GenDecl
	for _, decl := range f.Decls {
		gen, ok := decl.(*ast.GenDecl)
		if !ok || gen.Tok != token.IMPORT {
			continue
		}
		out = append(out, gen)
	}
	return out
}

// group identifiers understood by -imports-order.
const (
	groupStd     = "std"
	groupGeneral = "general"
